/**
 * @event
 * @name scwin.shrsTable_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
 */
// TODO Stage2: 중복 정의 — as-is 에서 뒤 정의에 덮여 호출되지 않던 본문(JS 는 마지막 정의가 이긴다). 필요 없으면 삭제 — 원이름 shrsTable_oncellclick

/**
 * @method
 * @name shrsTable_oncellclick_1
 * @description shrs Table oncellclick 1 처리
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.shrsTable_oncellclick_1 = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_listShrsList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_listShrsList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.deleteRow("this"); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'shrsTable.oncellclick' });
    }
};

