 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.shrsTable_oncellclick = function (rowIndex, columnIndex, columnId) {
    try { if (columnId === '_del') { const d = $c.util.getComponent('dlt_listShrsList'); if (d && d.removeRow) { d.removeRow(rowIndex); } if (typeof scwin.calFlowPosblShrs === 'function') { scwin.calFlowPosblShrs(); } return; }
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil55200n2.shrsTable_oncellclick' }); }
};

/**
