    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil55200n2.shrsTable_oneditend' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_regist
 * @description regist 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_regist = async function () {
    const sbmOptions = {
        id: "tx_fn_regist",
        method: "post",
        action: "/listInvstg/listShrs.do",
        ref: "dma_registReq",
        target: "dlt_listShrsList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
