/**
 * @method
 * @name calFlowPosblShrs
 * @description cal Flow Posbl Shrs 처리
 * @returns {void}
 * @hidden N
 */
scwin.calFlowPosblShrs = function () {
    const trdObjStkTpCdItem = $c.util.getComponent('ipt_trdObjStkTpCd');
    let isuShrs = 0;
    let flowPosblShrs = 0;
    let flowPosblShrsIndex = 0;
    for (let i = 0; i < trdObjStkTpCdItem.length; i++) {
        const trdObjStkTpCd = $c.util.getComponent('ipt_trdObjStkTpCd')[i].value;
        isuShrs = $c.util.getComponent('isuShrs')[i].value.replace(/^\$|,/g, "") + "";
        if (isuShrs === '') {
            isuShrs = '0';
        }
        if (trdObjStkTpCd === '6') {
            flowPosblShrsIndex = i;
            continue;
        }
        if (trdObjStkTpCd === '1') {
            flowPosblShrs += parseInt(isuShrs);
        } else {
            flowPosblShrs -= parseInt(isuShrs);
        }
    }
    if (flowPosblShrs === 0) {
        $c.util.getComponent('flowPosblShrs')[flowPosblShrsIndex].value = flowPosblShrs;
    } else {
        $c.util.getComponent('flowPosblShrs')[flowPosblShrsIndex].value = $c.num.formatNumber(flowPosblShrs);
    }
};

/**
 * @method
 * @name deleteRow
 * @description delete Row 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.deleteRow = function (obj) {
    const table = $c.util.getComponent('shrsTable');
    table.deleteRow(obj.parentNode.parentNode.rowIndex);
    scwin.calFlowPosblShrs();
};

/**
 * @method
 * @name regist
 * @description regist 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.regist = async function () {
    const frm = $c.util.getComponent('ListShrsForm');
    let checkCnt = 0;
    for (let i = 0; i < (function(){ throw 'unresolved:list:prtdepoWithdList'; })(); i++) {
        checkCnt++;
        checkCnt++;
    }
    if (checkCnt === 0) {
        $c.util.getComponent("dma_registReq").set("method", 'insertListShrs');
        $c.util.getComponent("dma_registReq").set("method", 'updateListShrs');
        frm.action = 'listShrs.do';
        await scwin.tx_fn_regist();
    } else {
        await $c.win.alert("의무보유 중 의무보유 기간 항목이 없는 부분이 있습니다.\n수정후 저장하세요.");
    }
};

