/**
 * @method
 * @name openPrtdepoWin
 * @description open Prtdepo Win 처리
 * @param {String} prtdepoId prtdepoId
 * @param {String} shrhdNm shrhdNm
 * @param {*} lstPrtdepoShrs lstPrtdepoShrs
 * @param {*} prtdepoWithdApplSeq prtdepoWithdApplSeq
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} listProcsSeq listProcsSeq
 * @param {String} prtdepoStrtDd prtdepoStrtDd
 * @param {String} prtdepoEndDd prtdepoEndDd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openPrtdepoWin = async function (prtdepoId, shrhdNm, lstPrtdepoShrs, prtdepoWithdApplSeq, bzProcsNo, listProcsSeq, prtdepoStrtDd, prtdepoEndDd) {
    if (listProcsSeq === '1') {
        const prtdepoWin = {};
        prtdepoWin.prtdepoId = prtdepoId;
        prtdepoWin.shrhdNm = shrhdNm;
        prtdepoWin.bzProcsNo = bzProcsNo;
        prtdepoWin.lstPrtdepoShrs = lstPrtdepoShrs;
        prtdepoWin.prtdepoWithdApplSeq = prtdepoWithdApplSeq;
        prtdepoWin.prtdepoStrtDd = prtdepoStrtDd;
        prtdepoWin.prtdepoEndDd = prtdepoEndDd;
        prtdepoWin.calcelYn = 'Y';
        const url = "/jldfil55210/jldfil55210.xml";
        const style = "dialogWidth:450px;dialogHeight:350px;scroll:no;resize:no";
        Object.assign(prtdepoWin, (await $c.win.openPopup(url, { type: 'pageFramePopup', modal: true }, prtdepoWin)) || {});
        if (prtdepoWin.calcelYn === 'N') {
            const frm = $c.util.getComponent('ListShrsForm');
            $c.util.getComponent("dma_registReq").set("method", 'searchListShrs');
            frm.action = 'listShrs.do';
            const nr = await scwin.tx_fn_openPrtdepoWin();
            if (nr && nr.responseJSON && nr.responseJSON.success === true) {
                $c.win.moveUrl("/jldfil55200/jldfil55200.xml", { "method": 'searchListShrs' });
            }
        }
    } else {
        await scwin.openNewPrtdepoWin(bzProcsNo, prtdepoId);
    }
};

/**
 * @method
 * @name openNewPrtdepoWin
 * @description open New Prtdepo Win 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} prtdepoId prtdepoId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openNewPrtdepoWin = async function (bzProcsNo, prtdepoId) {
    const prtdepoWin = {};
    prtdepoWin.calcelYn = 'Y';
    const url = "/jldfil55220/jldfil55220.xml?method=selectDepo&bzProcsNo=" + bzProcsNo + "&prtdepoId=" + prtdepoId + "&isurCd=" + $c.util.getComponent('ipt_isurCd').getValue();
    const style = "dialogWidth:730px;dialogHeight:430px;scroll:no;resize:no";
    Object.assign(prtdepoWin, (await $c.win.openPopup(url, { type: 'pageFramePopup', modal: true }, prtdepoWin)) || {});
    if (prtdepoWin.calcelYn === 'N') {
        const frm = $c.util.getComponent('ListShrsForm');
        $c.util.getComponent("dma_registReq").set("method", 'searchListShrs');
        frm.action = 'listShrs.do';
        const nr = await scwin.tx_fn_openNewPrtdepoWin();
        if (nr && nr.responseJSON && nr.responseJSON.success === true) {
            $c.win.moveUrl("/jldfil55200/jldfil55200.xml", { "method": 'searchListShrs' });
        }
    }
};

/**
 * @method
 * @name toList
 * @description to List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.toList = async function () {
    if (!await $c.win.confirm('메뉴를 이동하면 저장 이후 수정된 내용은 반영되지 않습니다.\n 이동하시겠습니까?')) {
        return;
    }
    const frm = (document.ListShrsForm || { elements: [] });
    frm.action = "listPrelmInvstg.do";
    $c.util.getComponent("dma_registReq").set("method", "listPrelmInvstgList");
    await scwin.tx_fn_toList();
};

